mapper.select:
SELECT FROM rent_listing l WHERE l.region_code IN
#{code}
AND l.monthly_rent <= #{maxMonthly} AND l.del_yn = 'N' ORDER BY l.monthly_rent ASC

SELECT COUNT(*) AS sampleCount, AVG(l.monthly_rent) AS avgMonthlyRent, AVG(l.deposit) AS avgDeposit, AVG(l.area_sqm) AS avgAreaSqm, AVG(l.built_year) AS avgBuiltYear, AVG(l.floor) AS avgFloor, AVG(l.monthly_rent / NULLIF(l.area_sqm, 0)) AS avgRentPerSqm, MIN(l.monthly_rent) AS rentMin, MAX(l.monthly_rent) AS rentMax, SUM(CASE WHEN l.monthly_rent < #{monthlyRent} THEN 1 ELSE 0 END) AS lowerCount FROM rent_listing l WHERE l.del_yn = 'N' AND l.listing_id != #{listingId} AND l.estate_type = #{estateType}
AND l.region_code = #{regionCode}
AND l.umd_name = #{umdName}
AND l.area_sqm BETWEEN #{areaMin} AND #{areaMax}
